// ============ CONFIGURATION ============
const APPOINTMENT_LENGTH_MINUTES = 30;
const DAY_START_TIME = "08:00";
const DAY_END_TIME = "17:00";
const SLOT_INCREMENT_MINUTES = 30;
const DAYS_TO_LOOK_AHEAD = 7;
// ========================================

const busyEvents = $input.all();
const setMainData = $('Set Main').first().json;
const currentTime = DateTime.fromISO(setMainData.current_time);
const requestedTime = DateTime.fromISO(setMainData.requested_time);

const today = currentTime.startOf('day');
const requestedDay = requestedTime.startOf('day');
const requestedDateStr = requestedDay.toFormat('yyyy-MM-dd');

function getDatePhrase(targetDate, today) {
  const daysDifference = Math.round(targetDate.startOf('day').diff(today, 'days').days);
  if (daysDifference === 0) return 'today';
  if (daysDifference === 1) return 'tomorrow';
  if (daysDifference >= 2 && daysDifference <= 7) return `this coming ${targetDate.toFormat('EEEE')}`;
  return targetDate.toFormat('EEEE, MMMM d');
}

function isDateBlockedByAllDay(dateToCheck, busyEvents) {
  return busyEvents.some(item => {
    const event = item.json;
    if (event.start && event.start.date && event.end && event.end.date) {
      const eventStartDate = DateTime.fromISO(event.start.date);
      const eventEndDate = DateTime.fromISO(event.end.date);
      return dateToCheck >= eventStartDate && dateToCheck < eventEndDate;
    }
    return false;
  });
}

function getBusySlotsForDate(dateStr, busyEvents) {
  return busyEvents
    .map(item => item.json)
    .filter(event => {
      if (!event.start || !event.start.dateTime) return false;
      const eventStart = DateTime.fromISO(event.start.dateTime);
      return eventStart.toFormat('yyyy-MM-dd') === dateStr;
    })
    .map(event => ({
      start: DateTime.fromISO(event.start.dateTime),
      end: DateTime.fromISO(event.end.dateTime)
    }))
    .sort((a, b) => a.start.toMillis() - b.start.toMillis());
}

function isSlotBusy(slot, busySlots) {
  return busySlots.some(busy => slot.start < busy.end && slot.end > busy.start);
}

function getAvailableSlotsForDate(dateStr, busyEvents, currentTime) {
  const dayStart = DateTime.fromISO(`${dateStr}T${DAY_START_TIME}:00`);
  const dayEnd = DateTime.fromISO(`${dateStr}T${DAY_END_TIME}:00`);
  const busySlots = getBusySlotsForDate(dateStr, busyEvents);
  const availableSlots = [];
  let slotStart = dayStart;
  while (slotStart.plus({ minutes: APPOINTMENT_LENGTH_MINUTES }) <= dayEnd) {
    const slot = {
      start: slotStart,
      end: slotStart.plus({ minutes: APPOINTMENT_LENGTH_MINUTES }),
      time: slotStart.toFormat('HH:mm')
    };
    if (slot.start >= currentTime && !isSlotBusy(slot, busySlots)) {
      availableSlots.push(slot.time);
    }
    slotStart = slotStart.plus({ minutes: SLOT_INCREMENT_MINUTES });
  }
  return availableSlots;
}

function formatTimeSlotsMessage(slots) {
  if (slots.length === 1) return slots[0];
  const timesForMessage = [...slots];
  const lastSlot = timesForMessage.pop();
  return `${timesForMessage.join(', ')}, and ${lastSlot}`;
}

const requestedDatePhrase = getDatePhrase(requestedDay, today);
let requestedDaySlots = [];
let requestedDayBlocked = false;

if (isDateBlockedByAllDay(requestedDay, busyEvents)) {
  requestedDayBlocked = true;
} else {
  requestedDaySlots = getAvailableSlotsForDate(requestedDateStr, busyEvents, currentTime);
}

const requestedDayHasSlots = requestedDaySlots.length > 0;

const weekAvailability = [];
for (let i = 0; i < DAYS_TO_LOOK_AHEAD; i++) {
  const checkDate = today.plus({ days: i });
  const checkDateStr = checkDate.toFormat('yyyy-MM-dd');
  if (isDateBlockedByAllDay(checkDate, busyEvents)) {
    weekAvailability.push({ date: checkDateStr, datePhrase: getDatePhrase(checkDate, today), dayName: checkDate.toFormat('EEEE'), slots: [], blockedByAllDayEvent: true });
  } else {
    const slots = getAvailableSlotsForDate(checkDateStr, busyEvents, currentTime);
    weekAvailability.push({ date: checkDateStr, datePhrase: getDatePhrase(checkDate, today), dayName: checkDate.toFormat('EEEE'), slots: slots, blockedByAllDayEvent: false });
  }
}

const firstAvailableDay = weekAvailability.find(day => day.slots.length > 0);
const totalSlotsInWeek = weekAvailability.reduce((sum, day) => sum + day.slots.length, 0);

let message = '';
let returnedSlots = [];
let returnedDate = null;
let returnedDatePhrase = null;
let wasRequestedDayAvailable = false;

if (requestedDayHasSlots) {
  wasRequestedDayAvailable = true;
  returnedSlots = requestedDaySlots;
  returnedDate = requestedDateStr;
  returnedDatePhrase = requestedDatePhrase;
  message = `Available appointment times for ${requestedDatePhrase}: ${formatTimeSlotsMessage(requestedDaySlots)}`;
} else if (firstAvailableDay) {
  wasRequestedDayAvailable = false;
  returnedSlots = firstAvailableDay.slots;
  returnedDate = firstAvailableDay.date;
  returnedDatePhrase = firstAvailableDay.datePhrase;
  message = `Unfortunately, we couldn't find any available times for ${requestedDatePhrase}. However, here are the available appointment times for ${firstAvailableDay.datePhrase}: ${formatTimeSlotsMessage(firstAvailableDay.slots)}`;
} else {
  wasRequestedDayAvailable = false;
  message = `Unfortunately, we couldn't find any available times for ${requestedDatePhrase}, and there are no available appointment times in the next ${DAYS_TO_LOOK_AHEAD} days. All days are fully booked.`;
}

return [{
  json: {
    message: message,
    availableSlots: returnedSlots,
    returnedDate: returnedDate,
    returnedDatePhrase: returnedDatePhrase,
    requestedDate: requestedDateStr,
    requestedDatePhrase: requestedDatePhrase,
    wasRequestedDayAvailable: wasRequestedDayAvailable,
    totalSlotsFound: returnedSlots.length,
    totalSlotsInWeek: totalSlotsInWeek,
    weekAvailability: weekAvailability,
    searchStartDate: today.toFormat('yyyy-MM-dd'),
    daysSearched: DAYS_TO_LOOK_AHEAD
  }
}];

